head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > oncustomcopy]<br/>GridView 컴포넌트에서 사용자가 복사(Ctrl+C) 동작을 수행할 때 발생합니다.",
    "validation" : [
        "preventCopy 속성으로 복사(Ctrl+C)가 차단된 경우 oncustomcopy 이벤트가 발생하지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (preventCopy=true 고정 샘플)
//  - con 옵션 없음(고정). preventCopy=true 면 Ctrl+C 시 oncustomcopy 미발생을 검증한다.
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    //  - 트리거(Ctrl+C 복사)는 사용자 액션
    $c.gcm.createLabel('label="[전제] GridView 에 preventCopy=true 고정 (복사 차단).\n[절차] Body 셀 클릭 후 Ctrl+C 복사 시도.\n[확인] preventCopy=true 이므로 oncustomcopy 핸들러 출력이 결과창에 나오지 않으면(미발생) 정상입니다. 아래 붙여넣기 확인 (Ctrl+V) 영역에 Ctrl+V 해도 클립보드 값이 바뀌지 않습니다(복사 차단)."', '', 'label1');

    // 조건 설정
    //  - preventCopy : true (복사 차단). 사용자가 Ctrl+C 해도 복사 동작이 수행되지 않아 oncustomcopy 미발생
    let properties = {
        dataList: "data:dlt_bind",
        preventCopy: "true"
    };

    let cList = $c.gcm.createCList(properties);

    // oncustomcopy 이벤트 핸들러 부착 (preventCopy=true 라 정상 동작 시 미발생)
    let eList = $c.gcm.createEList(["oncustomcopy"]);

    // dataList 생성 (기본 데이터 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// oncustomcopy : 사용자가 복사(Ctrl+C) 동작을 수행할 때 발생
//  - preventCopy=true 면 복사 동작 자체가 수행되지 않아 이 핸들러가 호출되지 않음(미발생)
//  - 만약 출력이 나온다면 preventCopy 차단이 동작하지 않은 것
scwin.target1_oncustomcopy = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncustomcopy 발생 e.type : " + e.type);
    return true;
};



// 붙여넣기 확인(par_pasteArea) : 그리드에서 Ctrl+C 후 이 영역에 Ctrl+V 로 붙여넣으면 onchange 발생
//  - preventCopy=true 라 복사가 차단되므로 클립보드 값이 그리드 셀값으로 바뀌지 않음(변화 없음)
scwin.par_pasteArea_onchange = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let pasted = par_pasteArea.getValue();
    bottom.setReturnValue("붙여넣기된 클립보드 값 : " + pasted);
};
